/* Local TypeScript UI; no CDN, no third-party telemetry, no ad-platform writes. */
type Obj = Record<string, any>;
const localRemember = { get:(k:string)=>{try{return localStorage.getItem(k)}catch{return null}},set:(k:string,v:string)=>{try{localStorage.setItem(k,v)}catch{}} };
const $ = (s: string) => document.querySelector(s) as HTMLElement | null;
const state: Obj = {workspaces:[], ws:null, view:'dashboard', imports:[], runs:[], run:null, path:'live', i30:'', i7:'', mode:'auto', exposureTier:'gte5000', objective:'roi', restoredRun:false, omit7:false, omit30:false, filter:'all', query:'', page:0, busy:false, ledger:null, actions:[], modal:null, task:null, tab:'metrics', proposals:[], audit:[], cf:{contexts:[],planId:'',profiles:[],operations:[],diagnoses:[],diagnosis:null,error:''}};
const names: Obj={dashboard:'候选 TOP3',imports:'导入与对账',materials:'全量素材',settings:'策略与预算',actions:'追投与复核',history:'快照与回放'};
const actionNames: Obj={HOLD:'保持／诊断',WAIT_INPUT:'待补配置',HISTORY_ONLY:'仅供历史回放',WAIT_REVIEW:'等待复核',STOP_REVIEW:'暂停／回退复核',BUDGET_CONFLICT:'额度不足',NEW_BOOST_TEST:'新建限额测试',BUDGET_TEST:'预算试探',BID_TEST:'成本出价试探'};
const exposureLabels: Obj={all:'全部曝光（跨层总览）',gte5000:'5000次及以上', '2000_4999':'2000–4999次','1000_1999':'1000–1999次','500_999':'500–999次',lt500:'不足500次（低样本）',unknown:'曝光缺失／待核'};
const objectiveLabels: Obj={exposure:'最大化曝光',orders:'最大化成单',roi:'最大化ROI',legacy:'历史综合评分'};
const objectiveUnits: Obj={exposure:'曝光数 / 100元',orders:'净订单 / 100元',roi:'净ROI',legacy:'综合分 / 100'};
const statuses: Obj={draft:'待批准',approved:'已预留 · 待执行',executed:'已执行 · 待复核',reviewed:'已复核',cancelled:'已取消'};
const cfNames: Obj={dashboard:'素材诊断',imports:'导入与对账',materials:'素材标签',settings:'诊断规则',context:'计划上下文与能力',history:'诊断回收与复盘'};
const cfLabelKeys: Obj={content_type:'内容类型',hook:'开场钩子',value_proposition:'价值主张',person:'人物',scene:'场景',price_expression:'价格表达',duration_band:'时长区间'};
const cfDecisionNames: Obj={RETAIN_RACE:'保留赛马',OBSERVE:'继续观察',TEST_VARIANT:'补测变体',NEEDS_DATA:'继续观察',STOP_PRODUCTION:'停止生产',EXPAND_DIRECTION:'扩产方向'};
const isChengfang=()=>state.ws?.config?.delivery_mode==='chengfang';
const visibleNames=()=>isChengfang()?cfNames:names;
const escapeHtml=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] as string));
const e=escapeHtml;
const fmt=(v:any,n=2)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:n,minimumFractionDigits:n});
const money=(v:any)=>v===null||v===undefined?'—':'¥'+fmt(v/100);
const pct=(v:any)=>v===null||v===undefined?'—':(v>=0?'+':'')+fmt(v*100,1)+'%';
const dt=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const badge=(text:string,kind='')=>`<span class="badge ${kind}">${e(text)}</span>`;
const pathName=(p:string)=>p==='live'?'视频 → 直播':'视频 → 商品';
const toast=(text:string,error=false)=>{let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.className=error?'error':'';t.textContent=text;t.style.display='block';setTimeout(()=>{if(t)t.style.display='none'},5000)};
async function api(url:string,method='GET',body?:any):Promise<any>{const opt:RequestInit={method};if(body instanceof FormData)opt.body=body;else if(body!==undefined){opt.body=JSON.stringify(body);opt.headers={'Content-Type':'application/json'}}const r=await fetch('/api'+url,opt);let d:any;try{d=await r.json()}catch{throw new Error('服务器返回异常，请查看启动窗口')}if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d}
async function guard(fn:()=>Promise<any>){if(state.busy)return;state.busy=true;$('#busy')?.classList.add('show');try{await fn()}catch(err:any){toast(err.message||String(err),true)}finally{state.busy=false;$('#busy')?.classList.remove('show')}}
function setWorkspace(ws:any){state.ws=ws;localRemember.set('optimizer_workspace',ws.id);state.run=null;state.objective='roi';state.restoredRun=false;state.proposals=[];state.exposureTier=ws.kind==='demo'?'all':'gte5000';state.i30='';state.i7='';state.omit7=false;state.omit30=false;state.modal=null;state.page=0;state.cf={contexts:[],planId:'',profiles:[],operations:[],diagnoses:[],diagnosis:null,error:''}}
function cfEnsurePlan(){const available=state.cf.contexts.filter((x:Obj)=>x.path===state.path);if(!available.some((x:Obj)=>x.plan_id===state.cf.planId)){state.cf.planId=available[0]?.plan_id||'';state.cf.diagnosis=null}const imports=cfImports().slice().sort((a:Obj,b:Obj)=>String(b.period_end||'').localeCompare(String(a.period_end||'')));if(!imports.some((x:Obj)=>x.id===state.cf.currentId))state.cf.currentId=imports[0]?.id||'';if(!imports.some((x:Obj)=>x.id===state.cf.priorId&&x.id!==state.cf.currentId))state.cf.priorId=imports.find((x:Obj)=>x.id!==state.cf.currentId)?.id||''}
async function refreshCf(){cfEnsurePlan();const p=state.cf.planId;if(!p){state.cf.profiles=[];state.cf.operations=[];state.cf.diagnoses=[];state.cf.currentId='';state.cf.priorId='';return}const inputs=cfImports();if(!inputs.some((x:Obj)=>x.id===state.cf.currentId))state.cf.currentId=inputs[0]?.id||'';if(!inputs.some((x:Obj)=>x.id===state.cf.priorId&&x.id!==state.cf.currentId)){const current=inputs.find((x:Obj)=>x.id===state.cf.currentId);state.cf.priorId=inputs.find((x:Obj)=>x.id!==state.cf.currentId&&(!current||x.period_end<current.period_start))?.id||''}const w=state.ws.id;const [profiles,operations,diagnoses]=await Promise.all([api(`/workspaces/${w}/chengfang/materials?path=${encodeURIComponent(state.path)}&plan_id=${encodeURIComponent(p)}`),api(`/workspaces/${w}/chengfang/operations?path=${encodeURIComponent(state.path)}&plan_id=${encodeURIComponent(p)}`),api(`/workspaces/${w}/chengfang/diagnosis-runs?path=${encodeURIComponent(state.path)}&plan_id=${encodeURIComponent(p)}`)]);state.cf.profiles=profiles;state.cf.operations=operations;state.cf.diagnoses=diagnoses}
async function refresh(){state.workspaces=await api('/workspaces');if(!state.ws)return;state.ws=state.workspaces.find((x:Obj)=>x.id===state.ws.id)||state.workspaces[0];const w=state.ws.id;const [im,ru,le,ac,contexts]=await Promise.all([api(`/workspaces/${w}/imports`),api(`/workspaces/${w}/runs`),api(`/workspaces/${w}/ledger`),api(`/workspaces/${w}/actions`),api(`/workspaces/${w}/chengfang/contexts`)]);state.imports=im;state.runs=ru;state.ledger=le;state.actions=ac;state.cf.contexts=contexts;autoSelect();if(isChengfang())await refreshCf()}
function autoSelect(){const rows=state.imports.filter((x:Obj)=>x.status==='confirmed'&&x.path===state.path);if(!state.omit30&&!rows.some((x:Obj)=>x.id===state.i30))state.i30=rows.find((x:Obj)=>x.window===30)?.id||'';const end=rows.find((x:Obj)=>x.id===state.i30)?.period_end;if(!state.omit7&&!rows.some((x:Obj)=>x.id===state.i7&&(!end||x.period_end===end)))state.i7=rows.find((x:Obj)=>x.window===7&&(!end||x.period_end===end))?.id||''}
async function loadRankingSnapshot(id:string){
 const run=await api('/ranking-runs/'+id);
 state.run=run;state.objective=run.objective||'legacy';state.path=run.path;state.exposureTier=run.exposure_tier||'all';state.mode=run.mode==='ROLLING_WEEKLY'?'rolling':'auto';
 state.i30=run.snapshot_ids.find((key:string)=>state.imports.some((x:Obj)=>x.id===key&&x.window===30))||'';
 state.i7=run.snapshot_ids.find((key:string)=>state.imports.some((x:Obj)=>x.id===key&&x.window===7))||'';
 state.omit30=!state.i30;state.omit7=!state.i7;state.page=0;state.filter='all';state.query='';
 state.proposals=state.actions.filter((a:Obj)=>a.run_id===id&&a.status==='draft').map((a:Obj)=>a.payload);
 state.restoredRun=true;localRemember.set('optimizer_run_'+state.ws.id,id);
}
async function restoreRanking(){
 const saved=localRemember.get('optimizer_run_'+state.ws.id);
 const latest=state.runs.find((r:Obj)=>r.id===saved)||state.runs[0];
 if(latest)await loadRankingSnapshot(latest.id);
}
async function runRanking(){if(!state.i30&&!state.i7){state.view='imports';render();return}state.run=await api('/ranking-runs','POST',{workspace_id:state.ws.id,import_30:state.i30||null,import_7:state.i7||null,mode:state.mode,exposure_tier:state.exposureTier,objective:state.objective});state.restoredRun=false;localRemember.set('optimizer_run_'+state.ws.id,state.run.id);state.proposals=[];state.page=0;await refresh();render()}
function numInput(name:string,label:string,value:any,help='',options:Obj={}){return `<label class="field"><span>${e(label)}</span><input type="number" name="${e(name)}" value="${value===null||value===undefined?'':e(value)}" step="${options.step??'any'}" min="${options.min??0}" ${options.required?'required':''} placeholder="未填写"><small>${e(help)}</small></label>`}
function textInput(name:string,label:string,value:any,help='',type='text'){return `<label class="field"><span>${e(label)}</span><input type="${type}" name="${e(name)}" value="${e(value)}" placeholder="未填写"><small>${e(help)}</small></label>`}
function selectInput(name:string,label:string,value:any,opts:Obj,help=''){return `<label class="field"><span>${e(label)}</span><select name="${e(name)}">${Object.entries(opts).map(([v,t])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`).join('')}</select><small>${e(help)}</small></label>`}
function checkbox(name:string,label:string,value:any){return `<label class="check"><input type="checkbox" name="${e(name)}" ${value?'checked':''}><span>${e(label)}</span></label>`}
function hero(title:string,sub:string,buttons=''){return `<div class="hero"><div><span class="eyebrow">PAID VIDEO · DECISION WORKSPACE</span><h1>${title}</h1><p>${sub}</p></div><div class="hero-actions">${buttons}</div></div>`}
function empty(title:string,text:string,button=''){return `<div class="empty"><div class="empty-symbol">↗</div><h3>${e(title)}</h3><p>${e(text)}</p>${button}</div>`}
function kpi(label:string,value:string,sub:string){return `<div class="kpi"><span>${e(label)}</span><strong>${value}</strong><small>${e(sub)}</small></div>`}
function selectorBar(){const arr=state.imports.filter((x:Obj)=>x.status==='confirmed'&&x.path===state.path);const options=(days:number,id:string)=>`<option value="">${days===30?'不使用30天':'不使用7天，仅历史榜'}</option>`+arr.filter((i:Obj)=>i.window===days).map((i:Obj)=>`<option value="${i.id}" ${i.id===id?'selected':''}>${e(i.period_start)}—${e(i.period_end)}${i.complete?'':' · 部分导出'}</option>`).join('');return `<div class="toolbar"><div class="seg"><button data-action="path" data-value="live" class="${state.path==='live'?'active':''}">视频 → 直播</button><button data-action="path" data-value="product" class="${state.path==='product'?'active':''}">视频 → 商品</button></div><label>30天<select id="select30">${options(30,state.i30)}</select></label><label>7天<select id="select7">${options(7,state.i7)}</select></label><label>模式<select id="rankmode"><option value="auto" ${state.mode==='auto'?'selected':''}>冷启动／历史</option><option value="rolling" ${state.mode==='rolling'?'selected':''}>滚动周（需3周）</option></select></label><label>排序目标<select id="objective">${Object.entries(objectiveLabels).map(([k,v])=>`<option value="${k}" ${state.objective===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><label>最近7天曝光<select id="exposure-tier">${Object.entries(exposureLabels).map(([k,v])=>`<option value="${k}" ${state.exposureTier===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><button class="primary" data-action="rank">重新计算</button></div>`}
function workspaceBanner(){if(!state.ws)return '';if(state.ws.kind==='demo')return `<div class="notice">${badge('教学模拟','amber')} 当前数据、任务与资金均为合成教学示例。操作只写本地记录，不会触达千川。</div>`;if(state.ws.kind==='historical')return `<div class="notice">${badge('历史回放','amber')} 你的原始历史文件保持原日期。排名供复验参考，不把历史数据或演示阈值变成今日投放指令。</div>`;return `<div class="notice subtle">${badge('本地运行')} 数据只进入本机。当前先打分再排序，TOP3不代表已通过追投条件；本系统不会操作广告账户。</div>`}
function cfContext(){return state.cf.contexts.find((x:Obj)=>x.path===state.path&&x.plan_id===state.cf.planId)||null}
function cfImports(){return state.imports.filter((x:Obj)=>x.status==='confirmed'&&x.path===state.path&&x.window===7&&x.metadata?.plan_id===state.cf.planId&&x.metadata?.partition==='chengfang'&&x.metadata?.cost_basis==='marketing_cost'&&x.metadata?.cost_grain==='material_attributable')}
function cfTier(exposure:any){const n=Number(exposure);return !Number.isFinite(n)?'曝光缺失／待核':n>=5000?'5000次及以上':n>=2000?'2000–4999次':n>=1000?'1000–1999次':n>=500?'500–999次':'不足500次（低样本）'}
function cfErrorText(){const p=state.cf.planId,all=state.imports.filter((x:Obj)=>x.status==='confirmed'&&x.path===state.path);if(!p)return '缺少计划上下文：请先在“计划上下文与能力”保存当前路径的计划与能力标识。';if(all.some((x:Obj)=>x.metadata?.plan_id===p&&x.metadata?.partition!=='chengfang'))return '存在非成方分区导入，不能用于素材诊断。';if(all.some((x:Obj)=>x.metadata?.plan_id===p&&x.metadata?.reconciliation&&!x.metadata.reconciliation.reconciled))return '存在未对账的营销成本，不能计算素材ROI。';return state.cf.error||''}
function cfSelector(){const plans=state.cf.contexts.filter((x:Obj)=>x.path===state.path);const imports=cfImports();const context=cfContext();return `<div class="toolbar cf-selector"><div class="seg"><button data-action="path" data-value="live" class="${state.path==='live'?'active':''}">视频 → 直播</button><button data-action="path" data-value="product" class="${state.path==='product'?'active':''}">视频 → 商品</button></div><label>计划<select id="chengfang-plan"><option value="">选择当前路径计划</option>${plans.map((x:Obj)=>`<option value="${e(x.plan_id)}" ${x.plan_id===state.cf.planId?'selected':''}>${e(x.plan_id)} · ${e(x.config.status)}</option>`).join('')}</select></label><label>当前完整7天导入<select id="chengfang-current" ${context?'':'disabled'}><option value="">选择当前导入</option>${imports.map((x:Obj)=>`<option value="${e(x.id)}" ${x.id===state.cf.currentId?'selected':''}>${e(x.period_start)}—${e(x.period_end)} · ${e(x.scope)}</option>`).join('')}</select></label><label>前期非重叠7天导入<select id="chengfang-prior" ${context?'':'disabled'}><option value="">不选（只做单期诊断）</option>${imports.filter((x:Obj)=>x.id!==state.cf.currentId).map((x:Obj)=>`<option value="${e(x.id)}" ${x.id===state.cf.priorId?'selected':''}>${e(x.period_start)}—${e(x.period_end)}</option>`).join('')}</select></label><button class="primary" data-action="chengfang-diagnose" ${context&&state.cf.currentId?'':'disabled'}>生成素材诊断</button></div>`}
function cfFrozen(d:any){const p=d.payload||d;const f=p.frozen_inputs||{};const ctx=f.plan_context||{};const periods=(f.import_ids||[]).map((id:string)=>{const i=state.imports.find((x:Obj)=>x.id===id);return i?`${i.period_start}—${i.period_end}`:id}).join('；');return `<div class="notice" data-testid="diagnosis-frozen">${badge('冻结诊断','amber')} 冻结周期：${e(periods||'导入快照 '+(f.import_ids||[]).join('、'))} · 分区：${e(p.partition||'chengfang')} · 计划：${e(d.plan_id||ctx.plan_id)} · 成本口径：${e(p.basis||f.cost_basis)}<br>冻结能力：基础投放 ${ctx.base_delivery?'是':'否'}／星选 ${ctx.star_select?'是':'否'}／达人营销 ${ctx.creator_marketing?'是':'否'}／佣金出价 ${ctx.creator_commission_bid?'是':'否'}／状态 ${e(ctx.status||'—')} · 上下文版本 ${e(f.context_revision??'—')}。页面只读取此已保存的诊断结果，不按当前标签、上下文或配置重新计算。</div>`}
function cfOverview(p:any){const rows=p.material_cards||[];const objectives:[string,string][]=[['exposure','最大化曝光'],['orders','最大化成单'],['roi','最大化ROI']];const tiers=['5000次及以上','2000–4999次','1000–1999次','500–999次','不足500次（低样本）','曝光缺失／待核'];return `<details class="panel" open><summary>三个目标 × 冻结曝光分层概览</summary><p>仅展示已保存诊断中的原始值与ROI平滑值；不从当前数据重新计算排序。</p><div class="table-wrap"><table><thead><tr><th>冻结曝光层</th>${objectives.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${tiers.map(tier=>`<tr><td>${e(tier)}<small>${rows.filter((x:Obj)=>cfTier(x.raw_metrics?.exposure)===tier).length} 条</small></td>${objectives.map(([key])=>`<td>${rows.filter((x:Obj)=>cfTier(x.raw_metrics?.exposure)===tier).map((x:Obj)=>`<p>${e(x.creative_id)} · <b>${fmt(x.objective_metrics?.[key])}</b>${key==='roi'?`<small>平滑 ${fmt(x.objective_metrics?.smoothed_roi)}</small>`:''}</p>`).join('')||'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
function cfMaterialCard(card:any,p:any){const f=p.frozen_inputs||{},ctx=f.plan_context||{},raw=card.raw_metrics||{},metric=card.objective_metrics||{},reference=p.material_reference||{},labels=card.labels||[];const groupCount=(p.direction_cards||[]).find((g:Obj)=>JSON.stringify(g.labels)===JSON.stringify(labels))?.creative_count||0;const warning=[...(card.warnings||[]),...(p.warnings||[])];return `<article class="panel cf-card"><div class="flex"><div><h3>${e(card.creative_id)}</h3><small>${badge(card.sample_state,'amber')} · ${e(cfTier(raw.exposure))}</small></div><button class="text-btn" data-action="chengfang-labels" data-id="${e(card.creative_id)}">编辑标签</button></div><p>冻结周期 ${e((f.import_ids||[]).join('、'))} · 分区 ${e(p.partition)} · 计划 ${e(ctx.plan_id||'—')} · 能力状态 ${e(ctx.status||'—')} · 口径 ${e(p.basis)}</p><div class="chips">${labels.map((x:string)=>badge(x)).join('')||badge('标签缺失','amber')} ${labels.length?badge(`同组 ${groupCount} 条`):''}</div><div class="detail-metrics"><div><small>原始曝光</small><b>${fmt(raw.exposure,0)}</b></div><div><small>营销消耗</small><b>${money(raw.marketing_cost)}</b></div><div><small>净订单</small><b>${fmt(raw.orders,0)}</b></div><div><small>净成交金额</small><b>${money(raw.net_gmv)}</b></div><div><small>原始 ROI</small><b>${fmt(raw.roi)}</b></div><div><small>平滑 ROI</small><b>${fmt(metric.smoothed_roi)}</b></div></div><p>数据权重：${e(card.period_count||1)} / ${e(f.config?.diagnosis_required_periods||2)} 个可比周期 · 计划参考 ROI ${fmt(reference.roi)} · 参考样本 ${fmt(reference.creative_count,0)} 条。</p><p>前期变化：曝光 ${pct(card.previous_period_change?.exposure)} · 订单 ${pct(card.previous_period_change?.orders)} · ROI ${pct(card.previous_period_change?.roi)}</p>${warning.length?`<div class="warning-list">${warning.map((x:string)=>`<p>${e(x)}</p>`).join('')}</div>`:''}<p><b>${e(cfDecisionNames[card.decision]||card.decision)}</b> · 原因 ${e((card.reason_codes||[]).join('；')||'—')} · 证据为冻结的本期／前期完整7天导入。下次复盘：下一期完整、同范围、同上下文的7天导入后。</p></article>`}
function cfDirectionCard(card:any){const b=card.brief||{};return `<article class="panel cf-direction"><div class="flex"><h3>${e(cfDecisionNames[card.decision]||card.decision)}</h3>${badge(card.decision,'amber')}</div><p>${(card.labels||[]).map((x:string)=>badge(x)).join('')} · ${card.creative_count} 条素材 · ${card.period_count} 个可比周期</p><div class="detail-metrics">${['exposure','orders','roi'].map(key=>`<div><small>${e(objectiveLabels[key])}</small><b>${fmt(card.objective_metrics?.[key])}</b><p>计划参考 ${fmt(card.plan_reference?.[key])} · 相对 ${pct((card.relative_efficiencies?.[key]??0)-1)}</p></div>`).join('')}</div><p>原因 ${e((card.reason_codes||[]).join('；')||'—')} · 证据为冻结计划参考和两期导入。下次复盘：下一期完整7天后核对同一组。</p>${['TEST_VARIANT','EXPAND_DIRECTION'].includes(card.decision)?`<div class="notice">保留变量：${e((b.retain_labels||[]).join('／')||'—')}；只改变一个变量：${e(b.change_label||'—')}；生产数量：${e(b.produce_count||'—')}；与前期比较：${e(b.comparison_direction||'—')}。</div>`:''}</article>`}
function cfContentDecisions(p:any){const groups:Obj={RETAIN_RACE:[],OBSERVE:[],TEST_VARIANT:[],STOP_PRODUCTION:[],EXPAND_DIRECTION:[]};for(const c of p.direction_cards||[])groups[c.decision]??=[];for(const c of p.direction_cards||[])groups[c.decision]?.push(c);for(const c of p.material_cards||[])if(['OBSERVE','TEST_VARIANT'].includes(c.decision))groups[c.decision].push(c);return `<section data-testid="content-decisions"><div class="section-head"><div><h2>内容决策</h2><p>方向与素材证据分别保留；没有充分证据时继续观察或补测。</p></div></div>${Object.entries(groups).map(([decision,cards])=>`<div class="cf-decision-group"><h3>${e(cfDecisionNames[decision])}</h3>${(cards as any[]).length?(cards as any[]).map(c=>c.creative_id?cfMaterialCard(c,p):cfDirectionCard(c)).join(''):'<p class="muted">当前冻结诊断没有此类结论。</p>'}</div>`).join('')}</section>`}
function chengfangDashboard(){const diagnosis=state.cf.diagnosis;const error=cfErrorText();let body=hero('让内容生产，<em>依据冻结证据。</em>','成方计划按完整、已确认的营销消耗导入诊断素材与内容方向。不会生成预算、出价或审批动作。')+cfSelector();if(error)body+=`<div class="notice">${badge('诊断受阻','amber')}${e(error)}</div>`;if(!diagnosis)return body+empty('选择计划与完整7天导入','计划必须属于当前路径；没有计划上下文时，诊断与标签编辑会保持禁用。');const p=diagnosis.payload||{};body+=cfFrozen(diagnosis)+`<div class="section-head"><div><h2>素材诊断</h2><p>生成于 ${e(dt(diagnosis.created_at))} · 已保存的输入不可被后续修改覆盖。</p></div><a class="ghost" href="/api/chengfang/diagnosis-runs/${e(diagnosis.id)}/export">导出诊断 CSV ↗</a></div>`+cfOverview(p)+cfContentDecisions(p);return body}
function dashboard(){if(isChengfang())return chengfangDashboard();const r=state.run;let body=hero('让下一笔预算，<em>有据可投。</em>','先排值得复验的素材，再检查当前任务与授权。不是每天都要加价。',`<button class="secondary" data-action="view" data-value="imports">＋ 导入数据</button>`)+selectorBar();if(!r&&state.imports.some((i:Obj)=>i.status==='confirmed'))return body+empty('报表已保存，等待计算','导入记录仍在本机。请选择报表与曝光层后点击重新计算。',`<button class="primary" data-action="rank">计算已导入报表</button>`);if(!r)return body+empty('上传数据，开始第一轮判断','原始千川Excel直接导入。只有30天也能看历史榜；补7天后形成近期TOP3。',`<div class="inline-buttons"><button class="primary" data-action="view" data-value="imports">导入我的数据</button><button class="secondary" data-action="load-real">载入合成示例</button><button class="ghost" data-action="demo">模拟追投完整流程 →</button></div>`);
 if(state.restoredRun)body+=`<div class="notice">已恢复上次查看的排名（${e(dt(r.created_at))}）。新增报表或修改参数后，请点击“重新计算”更新。</div>`;
 const s=r.summary_30;const main=r.results.filter((x:Obj)=>r.top_ids.includes(x.creative_id));body+=`<div class="kpis">${kpi('导出实际消耗',money(s.spend),'当前路径、原导出范围；含集合')}${kpi('报表净成交',money(s.net_gmv),'不等于全部退款成熟收入')}${kpi('汇总净ROI',fmt(s.spend>0?s.net_gmv/s.spend:null),'净额合计 ÷ 消耗合计')}${kpi('本轮候选',`${main.length}<i> / 3</i>`,'当前曝光层内取前三；不足三条按实际展示')}</div>`;
 body+=`<div class="section-head"><div><h2>${r.ranking_policy==='score_first'?(objectiveLabels[r.objective||'legacy']+' · 曝光分层 TOP3'):(r.mode==='HISTORY_30D'?'历史参考 TOP3':'优先复验 TOP3')}</h2><p>参考截至 ${e(r.period_end)} · ${e(pathName(r.path))} · ${r.complete?'完整导出':'仅当前导入子集'} · ${r.mode==='ROLLING_WEEKLY'?'周级滚动':'冷启动评分'}</p></div><div class="inline-buttons"><a class="ghost" href="/api/exports/${r.id}">导出排名 CSV ↗</a><button class="primary" data-action="propose" ${main.length?'':'disabled'}>生成追投建议</button></div></div>`;
 body+=exposurePanel(r);body+=objectiveOverview(r);if(r.warnings.length)body+=`<div class="warning-list">${r.warnings.map((w:string)=>`<p>ⓘ ${e(w)}</p>`).join('')}</div>`;
 if(!state.ws.config.threshold_confirmed)body+=`<div class="notice">追投门槛ROI ${fmt(state.ws.config.roi_min)} 为演示参数，不用于排除排名对象。追投门槛仍需业务确认。<button class="text-btn" data-action="view" data-value="settings">确认策略与预算 →</button></div>`;
 body+=main.length?`<div class="top-grid">${main.map((x:Obj,index:number)=>topCard(x,index)).join('')}</div>`:empty('当前曝光层暂无素材','可切换其他曝光层；只有30天或缺少7天曝光时，请选择“曝光缺失／待核”。',`<button class="secondary" data-action="view" data-value="materials">查看全部素材</button>`);
 if(state.proposals.length)body+=`<div class="section-head"><div><h2>本轮动作提案</h2><p>排名不直接换算加价；先检查任务、证据与风险。</p></div></div><div class="proposal-grid">${state.proposals.map((p:Obj)=>proposalCard(p)).join('')}</div>`;
 body+=`<div class="bottom-panels"><div class="panel"><h3>数据与追投状态（不影响入榜）</h3><div class="chips">${Object.entries(r.queue_counts).map(([key,value])=>`<button data-action="queue" data-value="${e(key)}">${({main:'放量复验',history:'历史',explore:'探索',observe:'观察修复',data:'数据待核',inactive:'无近期消耗'} as Obj)[key]} <b>${value}</b></button>`).join('')}</div></div><div class="panel"><h3>当前算法</h3>${r.objective&&r.objective!=='legacy'?`<p>${e(objectiveLabels[r.objective])}：按7天平滑效率降序，同值按自身权重、素材ID排序。</p><small>参考消耗 ${fmt(r.config.smoothing_yuan)}元；不混入趋势与稳定性权重。以下综合评分仅供历史诊断。</small>`:''}<p>30天 30% · 7天 40% · 趋势 20% · 稳定性 10%</p><small>按配置权重评分；冷启动实际为33.3%／44.4%／22.2%（默认配置）。小额消耗做ROI平滑；缺失ROI用同路径参考值，缺趋势按50分。原始缺失值保留；状态标签不筛掉排名对象。</small></div></div>`;return body}
function exposurePanel(r:Obj){return `<div class="panel"><h3>最近7天曝光分层 · ${e(exposureLabels[r.exposure_tier||'all'])}</h3><p>同层按${e(objectiveLabels[r.objective||'legacy'])}排序，参考值不随分层改变。曝光量只表示样本规模，不代表统计置信度；结合订单、消耗和归因判断ROI。</p><div class="chips">${Object.entries(exposureLabels).map(([key,label])=>{const count=key==='all'?r.results.length:(r.exposure_groups||[]).find((g:Obj)=>g.id===key)?.count??0;return `<button class="${(r.exposure_tier||'all')===key?'primary':'secondary'}" data-action="exposure" data-value="${key}">${e(label)} <b>${count}</b></button>`}).join('')}</div></div>`}
function objectiveDetail(x:Obj){if(!x.objective_metrics)return '';return `<div class="panel"><h3>7天目标效率与平滑依据</h3><p>（实际产出 + 参考消耗 × 同口径平均效率）÷（实际消耗 + 参考消耗）。参考消耗 ${fmt(state.run.config.smoothing_yuan)} 元；金额已统一单位。各目标只使用产出和消耗均有效的记录计算合计比率。</p><div class="detail-metrics">${['exposure','orders','roi'].map(k=>{const d=x.objective_metrics[k];return `<div><small>${e(objectiveLabels[k])} · ${e(objectiveUnits[k])}</small><b>${fmt(d.value)}</b><p>同口径参考 ${fmt(d.reference)} · 自身权重 ${pct(d.own_weight)}</p><small>${d.imputed?'仅参考分，待验证':'有效实绩经平滑'}${d.value===null?' · 无可用参考':''}</small></div>`}).join('')}</div><p>${e(x.objective_note||'')}。零订单仍为实际零订单；参考分不是已经发生的成交。</p></div>`}
function objectiveOverview(r:Obj){if(!r.objective||r.objective==='legacy')return '';return `<details class="panel"><summary>三个目标 × 曝光分层 TOP3 总览</summary><p>各格子独立排序；不足三条按实际展示。值为平滑效率，缺失项仅作参考；共享计划预算不能按素材重复追加。</p><div class="table-wrap"><table><thead><tr><th>7天曝光层</th>${['exposure','orders','roi'].map(k=>`<th>${e(objectiveLabels[k])}<small>${e(objectiveUnits[k])}</small></th>`).join('')}</tr></thead><tbody>${(r.exposure_groups||[]).map((g:Obj)=>`<tr><td>${e(g.label)}<small>${g.count} 条</small></td>${['exposure','orders','roi'].map(k=>{const rows=r.results.filter((x:Obj)=>x.exposure_tier===g.id).slice().sort((a:Obj,b:Obj)=>{const x=a.objective_metrics[k],y=b.objective_metrics[k];return Number(x.value===null)-Number(y.value===null)||(y.value??0)-(x.value??0)||y.own_weight-x.own_weight||(a.creative_id<b.creative_id?-1:a.creative_id>b.creative_id?1:0)}).slice(0,3);return `<td>${rows.map((x:Obj,n:number)=>`<p>${n+1}. <button class="text-btn" data-action="detail" data-id="${e(x.creative_id)}">${e(x.creative_name)}</button><br><b>${fmt(x.objective_metrics[k].value)}</b> · ${x.objective_metrics[k].imputed?'仅参考分，待验证':x.metrics.net_orders_7d===0?'实际零净订单，待验证':'净订单 '+fmt(x.metrics.net_orders_7d,0)}</p>`).join('')||'暂无素材'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></details>`}
function topCard(x:Obj,index:number){const m=x.metrics;return `<article class="top-card"><div class="card-top"><span class="rank-no">0${index+1}</span>${badge(x.queue_label,'amber')}<button class="text-btn" data-action="detail" data-id="${e(x.creative_id)}">查看指标</button></div><h3 title="${e(x.creative_name)}">${e(x.creative_name)}</h3><div class="creative-id">${e(x.creative_id)}</div><div class="score"><strong>${fmt(state.run?.objective&&state.run.objective!=='legacy'?x.objective_value:x.score,2)}</strong><span>${e(objectiveUnits[state.run?.objective||'legacy'])}<br>平滑参考，不是增量预测</span></div><p>${badge(x.exposure_label||'曝光待核')} · 7天曝光 ${fmt(m.impressions_7d,0)}</p><div class="card-metrics"><div><small>7天净ROI</small><b>${fmt(m.roi_7d)}</b></div><div><small>30天净ROI</small><b>${fmt(m.roi_30d)}</b></div><div><small>${state.run?.mode==='HISTORY_30D'?'30天':'7天'}净订单</small><b>${fmt(state.run?.mode==='HISTORY_30D'?m.net_orders_30d:m.net_orders_7d,0)}</b></div></div><div class="reason"><p>${e(x.objective_note||'')}</p><p>7天实际消耗 ${money(m.spend_7d)}${state.run?.objective!=='legacy'&&x.objective_metrics?.[state.run?.objective]?' · 自身数据权重 '+pct(x.objective_metrics[state.run.objective].own_weight):''}</p><p>${e(x.exposure_note||'')}</p>${[...(x.scoring?.imputed||[]),...x.reasons].slice(0,3).map((s:string)=>`<p>${e(s)}</p>`).join('')}</div><div class="card-bottom"><span>${m.stability===null?'稳定性待积累':'周过线稳定性 '+fmt(m.stability,0)}</span><button class="text-btn" data-action="detail-task" data-id="${e(x.creative_id)}">配置追投 →</button></div></article>`}
function proposalCard(p:Obj){const actionable=['BUDGET_TEST','BID_TEST','NEW_BOOST_TEST'].includes(p.action_type);return `<div class="panel proposal"><div class="flex"><h3>${e(actionNames[p.action_type]||p.action_type)}</h3>${badge(p.simulated?'模拟':actionable?'待人工确认':'暂无数值动作')}</div><p class="truncate">${e(p.creative_name)}</p>${actionable?`<div class="proposal-values"><div><span>任务预算</span><b>${money(p.budget_old)} → ${money(p.budget_new)}</b></div><div><span>成本出价</span><b>${money(p.bid_old)} → ${money(p.bid_new)}</b></div></div>`:'<div class="notice"><strong>本轮未生成数值动作</strong> · 已完成检查，下方说明原因；不是请求失败。</div>'}<p>${e(p.reasons.join('；'))}</p>${p.required_inputs.length?`<div class="warning-list"><strong>待补充或确认</strong><ul>${p.required_inputs.map((v:string)=>`<li>${e(v)}</li>`).join('')}</ul></div>`:''}<div class="inline-buttons"><button class="secondary" data-action="detail-task" data-id="${e(p.creative_id)}">配置当前任务</button><button class="ghost" data-action="view" data-value="settings">策略与预算</button>${actionable?`<button class="primary" data-action="approve" data-id="${p.id}">批准并预留 ${money(p.reserve)}</button>`:''}</div></div>`}
function importsView(){return hero('原始报表，直接导入。','先确认窗口、路径与净额口径，再进入计算。缺失不是0，集合不是单视频。')+`<div class="import-start"><label class="dropzone" id="dropzone"><input type="file" id="uploads" accept=".xlsx,.csv" multiple><span class="upload-mark">↑</span><h2>选择或拖入30天／7天投放文件</h2><p>原始千川 .xlsx 或标准 .csv · 每份≤20MB · 支持多文件</p><span class="button primary">选择文件</span></label><div class="panel starter"><span class="eyebrow">已经为你准备</span><h3>先看合成示例，再试一轮操作</h3><p>合成示例使用虚构素材和金额，展示30天与7天的导入和排名；教学模拟用于体验预算与出价流程。</p><button class="secondary" data-action="load-real">载入4份合成示例</button><button class="ghost" data-action="demo">创建教学模拟工作区 →</button><a class="text-btn" href="/api/examples/template" download>标准 CSV 模板</a></div></div><div class="section-head"><h2>导入记录 <span>${state.imports.length}</span></h2></div>${state.imports.map((i:Obj)=>importCard(i)).join('')||'<p class="muted">还没有导入记录。</p>'}`}
function historyReuseForm(i:Obj){const plans=state.cf.contexts.filter((x:Obj)=>x.path===i.path);if(!plans.length)return `<small class="muted">先在“计划上下文与能力”保存 ${pathName(i.path)} 的计划，才能复用这份历史数据。</small>`;const options=Object.fromEntries(plans.map((x:Obj)=>[x.plan_id,`${x.plan_id} · ${x.config.status}`]));return `<details class="history-reuse"><summary>创建乘方诊断快照</summary><form data-form="reuse-history" data-id="${e(i.id)}" class="form-grid"><p class="notice">原始导入保持不变。将创建一份新的7天乘方快照，需确认素材消耗可归属，并与计划营销消耗完成对账。</p>${selectInput('plan_id','计划',plans[0].plan_id,options)}${textInput('scope','计划／导出范围',i.scope||'')}${numInput('plan_marketing_cost','该7天计划营销消耗（元）',null,'用于与素材成本合计对账')}<button class="primary">创建诊断快照</button></form></details>`}
function importCard(i:Obj){if(i.status==='confirmed'){const reusable=isChengfang()&&i.window===7&&i.metadata?.partition!=='chengfang';return `<div class="import-row"><div class="file-icon">X</div><div><h4>${e(i.filename)}</h4><p>${pathName(i.path)} · ${e(i.period_start)}—${e(i.period_end)} · ${i.totals.rows}条记录 · 单ID活跃${i.totals.active_single}条 · ${i.totals.invalid_rows}条待核</p>${reusable?historyReuseForm(i):''}</div>${badge('已确认')}<a class="ghost" href="/api/imports/${i.id}/source">原文件 ↗</a></div>`}const s=i.suggested;return `<form data-form="confirm-import" data-id="${i.id}" class="panel import-confirm"><div class="flex"><h3>${e(i.filename)}</h3>${badge('待确认','amber')}</div><div class="form-grid">${selectInput('path','成交路径',s.path||'live',{live:'视频 → 直播',product:'视频 → 商品'})}${textInput('period_start','开始日期',s.period_start||'','','date')}${textInput('period_end','截止日期',s.period_end||'','','date')}${textInput('scope','账户／计划及导出范围',state.ws.name,'内部标识，不从长文件名猜计划ID')}${selectInput('basis','净额口径',s.path==='live'?'net_1h':'reported_net',{reported_net:'报表净额（定义待确认）',net_1h:'报表净额（扣1小时退款）',matured_net:'成熟净额（已自行核实）'})}${textInput('basis_note','口径说明','报表净额不等于成熟经营利润')}</div><p>识别：${i.totals.rows}行，${i.totals.active_single}条单ID活跃记录，${i.totals.invalid_rows}条数据待核。${i.missing_fields.length?'必要字段未识别：'+e(i.missing_fields.join('、')):''}</p><details><summary>字段映射与表头位置</summary><div class="form-grid">${selectInput('sheet','工作表',i.sheet,Object.fromEntries(i.sheets.map((s:string)=>[s,s])))}${numInput('header_row','表头行号',i.header_row,'从1开始')}${Object.entries(i.mapping).map(([key,col])=>selectInput('map_'+key,key,col||'',{'':'未提供',...Object.fromEntries(i.headers.filter(Boolean).map((s:string)=>[s,s]))})).join('')}</div></details>${i.issues.length?`<details><summary>数据异常 ${i.issue_count} 条（不静默修复）</summary>${i.issues.slice(0,20).map((x:Obj)=>`<p>第${x.row}行：${e(x.messages.join('；'))}</p>`).join('')}</details>`:''}<div class="checks">${checkbox('complete','确认这是完整导出（取消则仅标记为已导入子集）',true)}${checkbox('scope_confirmed','已核对账户／计划范围、净额字段和统计窗口',false)}</div><button class="primary">确认并保存快照</button></form>`}
function cfMaterials(){const p=state.cf.diagnosis?.payload;const cards=p?.material_cards||[];return hero('素材标签，<em>按计划保存。</em>','标签固定为内容类型、钩子、价值、人物、场景、价格表达和时长。缺少计划时不可编辑。')+cfSelector()+(cfErrorText()?`<div class="notice">${e(cfErrorText())}</div>`:'')+(cards.length?`<div class="top-grid">${cards.map((x:Obj)=>cfMaterialCard(x,p)).join('')}</div>`:empty('先生成诊断','标签编辑在选定计划下保存；生成诊断后会显示冻结标签与完整原始指标。'))}
function materials(){if(isChengfang())return cfMaterials();let r=state.run;let head=hero('所有素材，都有解释。','所有独立素材先打分；小样本和缺失值平滑，原始实绩保持可追溯。')+selectorBar();if(!r)return head+empty('先运行一次排序','导入报表并计算后，这里显示全量评分与数据状态。');head+=exposurePanel(r);let rows=r.results.filter((x:Obj)=>((r.exposure_tier||'all')==='all'||x.exposure_tier===r.exposure_tier)&&(state.filter==='all'||x.queue===state.filter)&&(!state.query||(x.creative_name+x.creative_id).toLowerCase().includes(state.query.toLowerCase())));const total=rows.length;const max=Math.max(0,Math.ceil(total/30)-1);state.page=Math.min(state.page,max);rows=rows.slice(state.page*30,state.page*30+30);return head+`<div class="table-tools"><input id="search" placeholder="搜索素材名称或ID" value="${e(state.query)}"><select id="queuefilter"><option value="all">全部分层</option>${Object.entries({main:'放量复验',history:'历史参考',explore:'探索／新起量',observe:'观察修复',data:'数据待核',inactive:'无近期消耗'}).map(([k,v])=>`<option value="${k}" ${state.filter===k?'selected':''}>${v}</option>`).join('')}</select><span>${total} 条</span><a class="ghost" href="/api/exports/${r.id}">导出 CSV</a></div><div class="table-wrap"><table><thead><tr><th>素材 / 来源</th><th>队列</th><th>${e(objectiveUnits[r.objective||'legacy'])}</th><th>30天 ROI</th><th>7天 ROI</th><th>7天曝光 / 分层</th><th>7天消耗</th><th>7天净单</th><th>效率变化</th><th>操作</th></tr></thead><tbody>${rows.map((x:Obj)=>{const m=x.metrics;return `<tr><td class="material-cell"><b title="${e(x.creative_name)}">${e(x.creative_name)}</b><small>${e(x.creative_id)}</small></td><td>${badge(x.queue_label,x.queue==='main'?'amber':'')}</td><td class="numeric">${fmt(r.objective&&r.objective!=='legacy'?x.objective_value:x.score,2)}<small>${e(x.objective_note||'')}</small></td><td>${fmt(m.roi_30d)}</td><td>${fmt(m.roi_7d)}</td><td>${fmt(m.impressions_7d,0)}<small>${e(x.exposure_label||'待核')}</small></td><td>${money(m.spend_7d)}</td><td>${fmt(m.net_orders_7d,0)}</td><td>${pct(m.roi_growth)}</td><td><button class="text-btn" data-action="detail" data-id="${e(x.creative_id)}">详情 →</button></td></tr>`}).join('')}</tbody></table></div><div class="pagination"><button class="secondary" data-action="prev" ${state.page===0?'disabled':''}>上一页</button><span>${state.page+1} / ${max+1}</span><button class="secondary" data-action="next" ${state.page>=max?'disabled':''}>下一页</button></div>`}
function settings(){const c=state.ws.config;return hero('规则透明，边界先行。','权重、门槛和试探档位是管理规则，不是已经识别的最优参数。')+`<form data-form="settings" class="settings-grid"><div class="panel"><div class="section-head"><h2>投放模式</h2>${badge('工作方式')}</div>${selectInput('delivery_mode','投放方式',c.delivery_mode||'independent_boost',{independent_boost:'独立追投',chengfang:'乘方协同'},'选择后保存。乘方协同只做素材诊断和内容决策，不会生成预算、出价或批准操作。')}<p class="notice">已在乘方后台统一投放时，选择“乘方协同”，系统将按素材输出诊断和内容决策。</p></div><div class="panel"><div class="section-head"><h2>排序规则</h2>${badge('M01–M08')}</div><div class="form-grid">${numInput('roi_min','ROI评分标尺／追投筛选线',c.roi_min,'只用于分数换算与追投检查，不排除排名对象')}${numInput('min_orders','追投参考订单门槛',c.min_orders,'影响追投状态，不影响入榜',{step:1,min:1})}${numInput('smoothing_yuan','平滑强度（元）',c.smoothing_yuan,'只平滑一次，不再叠加订单乘数')}${numInput('reference_roi','固定参考ROI（可留空）',c.reference_roi,'为空时以同路径可比单素材汇总重算')}${numInput('freshness_days','数据新鲜度上限（天）',c.freshness_days,'超出只看历史，不给当前数值动作',{step:1,min:0})}</div>${textInput('threshold_note','筛选线来源与口径',c.threshold_note)}${checkbox('threshold_confirmed','我已确认本筛选线及其口径；它不自动等于利润保证',c.threshold_confirmed)}<details open><summary>四因子权重（可调整）</summary><div class="form-grid four">${Object.entries(c.weights).map(([k,v])=>numInput('w_'+k,({30:'30天',7:'7天',trend:'趋势',stability:'稳定性'} as Obj)[k]+'（%）',Number(v)*100,'',{min:0})).join('')}</div><small>冷启动去除稳定性权重后归一。只有30天时用历史分；模式不同不直接混排。</small></details></div><div class="panel"><div class="section-head"><h2>共享授权池</h2>${badge('M12')}</div><p>这里是本地授权账，不连接平台钱包。其他金额不要包含本应用已预留／已结算费用。</p><div class="form-grid">${numInput('budget_total','预算池总授权（元）',c.budget_total===null?null:c.budget_total/100,'未填时不产生数值追投建议')}${numInput('external_spent','其他已消耗（元）',(c.external_spent||0)/100,'排除本应用已结算追加额度')}${numInput('external_committed','其他在途授权（元）',(c.external_committed||0)/100,'含既有任务未花预算，排除本应用预留')}</div>${ledgerPanel()}<div class="notice">仅在本地批准时预留，人工执行后保持占用；完成复核后，已花部分结算，未花部分释放。不自动给三条素材重复授权。</div><button class="primary wide">保存规则与预算</button></div></form><div class="panel footprint"><h3>V1明确不计算的内容</h3><p>不把排名分当成功率；不以历史ROI×追加预算预测增量；没有SKU成本和完整退款时不认证利润；不自动登入或调价。</p></div>`}
function ledgerPanel(){const l=state.ledger;if(!l)return '';return `<div class="ledger"><div><small>本地可追加</small><strong>${money(l.free)}</strong></div><div><small>本应用在途预留</small><b>${money(l.reserved)}</b></div><div><small>本应用已结算</small><b>${money(l.settled)}</b></div>${l.deficit?`<p class="error-text">授权缺口 ${money(l.deficit)}，停止新授权</p>`:''}</div>`}
function actionsView(){return hero('每次追投，都留下证据。','本地批准 → 人工到平台执行 → 记录真实值 → 到期复核。未复核，不连续加价。')+`<div class="panel">${ledgerPanel()}<small>注意：下面的“记录执行”只写本地台账，系统从未操作广告账户。</small></div><div class="section-head"><h2>动作与复核记录</h2><button class="secondary" data-action="refresh">刷新</button></div>${state.actions.length?state.actions.map((a:Obj)=>{const p=a.payload;return `<div class="panel action-record"><div class="flex"><div><h3>${e(p.creative_name)}</h3><small>${e(pathName(a.path))} · ${e(a.creative_id)} · ${dt(a.created_at)}</small></div>${badge(statuses[a.status],a.status==='approved'||a.status==='executed'?'amber':'')}</div><div class="action-summary"><b>${e(actionNames[p.action_type])}</b>${['BUDGET_TEST','BID_TEST','NEW_BOOST_TEST'].includes(p.action_type)?`<span>预算 ${money(p.budget_old)} → ${money(p.budget_new)}</span><span>成本出价 ${money(p.bid_old)} → ${money(p.bid_new)}</span><span>本笔预留 ${money(a.reserved)}</span>`:'<span>本轮未生成数值动作，请查看下方原因。</span>'}</div><p>${e(p.reasons.join('；'))}</p>${a.execution?`<small>人工执行：${dt(a.execution.executed_at)} · 复核时间：${dt(a.execution.review_after)}</small>`:''}${a.review?`<div class="notice"><span>${a.review.maturity==='matured'?(a.review.passed?'复核过线':'未通过／证据不足'):'临时观察'}</span> · 同批净ROI ${fmt(a.review.observed_roi)} · ${e(a.review.note||'未填写备注')} ${a.review.rollback_suggestion?`<br>建议核查回退至预算${money(a.review.rollback_suggestion.budget)}／出价${money(a.review.rollback_suggestion.bid)}，未自动执行。`:''}</div>`:''}<div class="inline-buttons">${a.status==='draft'&&['BID_TEST','BUDGET_TEST','NEW_BOOST_TEST'].includes(p.action_type)?`<button class="primary" data-action="approve" data-id="${a.id}">批准并预留</button>`:''}${a.status==='approved'?`<button class="primary" data-action="execute-modal" data-id="${a.id}">记录平台已执行</button>`:''}${a.status==='executed'?`<button class="primary" data-action="review-modal" data-id="${a.id}">填写复核结果</button>`:''}${['draft','approved'].includes(a.status)?`<button class="ghost" data-action="cancel" data-id="${a.id}">取消未执行提案</button>`:''}</div></div>`}).join(''):empty('还没有追投提案','先在TOP3页面生成建议；缺当前配置时只给待补字段，不编造价格。')}`}
function historyView(){return hero('保存当时知道什么。','原文件、参数、排序与操作分别留痕。滚动7日差分，不是当日数据。',`<a class="secondary" href="/api/workspaces/${state.ws.id}/backup">导出工作区 JSON</a>`)+`<div class="panel"><h2>已保存的排序运行</h2><div class="table-wrap"><table><thead><tr><th>生成时间</th><th>数据截止</th><th>路径</th><th>模式</th><th>目标 / 曝光层</th><th>TOP数量</th><th></th></tr></thead><tbody>${state.runs.map((r:Obj)=>`<tr><td>${dt(r.created_at)}</td><td>${e(r.period_end)}</td><td>${pathName(r.path)}</td><td>${e(r.mode)}</td><td>${e(objectiveLabels[r.objective||'legacy'])}<small>${e(exposureLabels[r.exposure_tier||'all'])}</small></td><td>${r.top_ids.length}</td><td><button class="text-btn" data-action="load-run" data-id="${r.id}">查看当时结果 →</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel footprint"><h3>快照与导入</h3><p>当前工作区 ${state.imports.filter((i:Obj)=>i.status==='confirmed').length} 份已确认快照。后续需要至少3个可比非重叠周，才启用周过线稳定性。</p><button class="secondary" data-action="view" data-value="imports">查看源文件与对账</button><button class="ghost" data-action="audit">加载操作审计</button>${state.audit.length?`<div class="audit-list">${state.audit.slice(0,50).map((a:Obj)=>`<details><summary>${dt(a.created_at)} · ${e(a.event)}</summary><pre>${e(JSON.stringify(a.payload,null,2))}</pre></details>`).join('')}</div>`:''}</div>`}
function detailModal(){const x=state.modal.item,m=x.metrics,t=state.task||{};
 const ratio=(a:any,b:any)=>a!==null&&a!==undefined&&b!==null&&b!==undefined&&Number.isFinite(a)&&Number.isFinite(b)&&b>0?a/b:null;
 const utilization=ratio(t.spent,t.budget),bidSpace=t.pricing_mode==='cost_bid'?ratio(t.bid_cap,t.bid):null;
 const limits=[state.ledger?.free,t.addon_cap,t.risk_remaining,t.budget,t.spent];
 const addonLimit=limits.every(v=>typeof v==='number'&&Number.isFinite(v))?Math.max(0,Math.min(state.ledger.free,t.addon_cap,Math.max(0,t.risk_remaining-Math.max(0,t.budget-t.spent)))):null;
 let content='';if(state.tab==='metrics'){const items:[string,any,string,string][]=[['M01 · 30天净ROI',m.roi_30d,'V30 / S30','number'],['M02 · 7天净ROI',m.roi_7d,'V7 / S7','number'],['M03 · 7天净订单',m.net_orders_7d,'Q7，源表净成交订单数','int'],['M03 · 30天净订单',m.net_orders_30d,'Q30，源表净成交订单数','int'],['M03 · 7天消耗',m.spend_7d,'S7，源表整体消耗','money'],['M03 · 30天消耗',m.spend_30d,'S30，源表整体消耗','money'],['原始 · 7天净成交',m.net_gmv_7d,'V7，报表净额','money'],['原始 · 30天净成交',m.net_gmv_30d,'V30，报表净额','money'],['M04 · 30天平滑ROI',m.smooth_roi_30d,'(V30 + s0 × Rref) / (S30 + s0)','number'],['M04 · 前23天平滑ROI',m.smooth_roi_23d,'(V23 + s0 × Rref) / (S23 + s0)；需同口径且差额有效','number'],['M04 · 7天平滑ROI',m.smooth_roi_7d,'(V7 + s0 × Rref) / (S7 + s0)','number'],['M05 · 效率变化',m.roi_growth,'R7 / R23 − 1；需可比前期','percent'],['M06 · 日均净成交变化',m.gmv_growth,'(V7/7) / (V23/23) − 1','percent'],['M06 · 日均消耗变化',m.spend_growth,'(S7/7) / (S23/23) − 1','percent'],['M07 · 净额折减比例',m.net_discount_ratio,'1 − V7/G7；不是最终退款率','percent'],['M08 · 筛选线余量',m.roi_headroom,'平滑R7 / Rmin − 1；不是可安全加价比例','percent'],['M09 · 每笔净订单广告费',m.net_cpa_7d,'S7 / Q7；不冒充支付事件CPA','money'],['M10 · 当前任务预算使用率',utilization,'当前独立任务消耗 / 任务预算；需填写任务且预算大于0','percent'],['M11 · 当前成本出价空间',bidSpace===null?null:bidSpace-1,'批准出价上限 / 当前出价 − 1；需为成本出价任务且当前出价大于0','percent'],['M12 · 当前追加授权上限',addonLimit,'min(本地可用预算, 素材追加授权, 风险授权 − 当前任务未花预算)；最低0。需填写预算池与任务授权；本轮建议还受试探幅度及审批限制','money'],['M13 · 相邻周增长',m.week_growth,'最近周ROI / 上一非重叠周ROI − 1；需连续2周且前周ROI大于0','percent'],['M14 · 周过线稳定性',m.stability,'100 × 过线周消耗 / 各周消耗；至少3个连续可比周','number'],['诊断 · 7天曝光',m.impressions_7d,'源表整体展现次数','int'],['诊断 · 7天点击',m.clicks_7d,'源表整体点击次数','int'],['诊断 · 7天CTR',m.ctr_7d,'点击 / 曝光','percent'],['诊断 · 7天净订单CVR',m.net_cvr_7d,'净订单 / 点击','percent']];content=objectiveDetail(x)+`<div class="notice">${badge(x.queue_label)} ${badge(x.exposure_label||'曝光待核')} · ${e(x.exposure_note||'')} · ${e(x.mode_label)} · 全量评分 · 优先分 ${fmt(x.score,2)}。分数不代表利润率或成功概率。</div><p class="muted">M01–M09、M13–M14来自本次排名快照；M10–M12按打开详情时的当前任务与本地预算计算。缺失不当0；评分补值在下方“评分拆解”单列。</p><div class="detail-metrics">${items.map(([title,value,formula,kind])=>`<div><small>${e(title)}</small><b>${kind==='percent'?pct(value):kind==='money'?money(value):fmt(value,kind==='int'?0:2)}</b><p>${e(formula)}</p>${value===null||value===undefined?'<small>暂不可计算：所需数据缺失、不可比或分母为0；详见公式与下方数据提示。</small>':''}</div>`).join('')}</div><div class="panel"><h3>历史综合评分拆解（目标效率榜不使用此权重）</h3>${Object.entries(x.breakdown).map(([k,v])=>`<div class="barline"><span>${e(k)}</span><div><i style="width:${v===null?0:Math.min(100,Number(v))}%"></i></div><b>${fmt(v,1)}</b></div>`).join('')}<p>评分用ROI：30天 ${fmt(x.scoring?.roi_30d,4)}，7天 ${fmt(x.scoring?.roi_7d,4)}；缺失项为评分参考值，不是实绩。</p><p>实际权重：${Object.entries(x.scoring?.weights||{}).map(([k,v])=>`${e(k)} ${fmt(Number(v)*100,1)}%`).join(" · ")}</p><p>参考ROI ${fmt(state.run.ref_roi,4)}；s0＝${fmt(state.run.config.smoothing_yuan)}元；来源范围固定，不因筛选后再改基准。</p></div><div class="panel"><h3>判断依据与边界</h3>${[...x.reasons,...x.flags,...x.errors].map((s:string)=>`<p>· ${e(s)}</p>`).join('')}${m.week_points.length?`<div class="week-list">${m.week_points.map((w:Obj)=>`<span>${w.end}：ROI ${fmt(w.roi)}</span>`).join('')}</div>`:''}</div><div class="panel"><h3>原始来源</h3>${x.sources.map((s:Obj)=>`<p><a href="/api/imports/${s.import_id}/source">${e(s.filename)} ↗</a><br><small>${e(s.sheet)} · Excel第${s.row}行</small></p>`).join('')}<p>源表追投字段只展示、不重复加总：净额 ${money(x.boost_reported.boost_net_gmv)}，源追投ROI ${fmt(x.boost_reported.boost_roi)}。尚不能据此倒推出任务出价或消耗。</p></div>`}else content=taskForm(x);
return `<div class="modal-backdrop"><section class="modal wide-modal"><header><div><span class="eyebrow">CREATIVE DETAIL</span><h2>${e(x.creative_name)}</h2><small>${e(x.creative_id)} · ${pathName(x.path)}</small></div><button class="icon-btn" data-action="close">×</button></header><div class="seg detail-tabs"><button data-action="detail-tab" data-value="metrics" class="${state.tab==='metrics'?'active':''}">指标、理由与来源</button><button data-action="detail-tab" data-value="task" class="${state.tab==='task'?'active':''}">当前追投配置</button></div><div class="modal-body">${content}</div></section></div>`}
function taskForm(x:Obj){const t=state.task||{};const yn=(k:string)=>t[k]===null||t[k]===undefined?null:t[k]/100;return `<form data-form="task"><div class="notice">当前任务的数据由你确认。没有给定的预算、出价或任务效果保持空白；不拿素材历史代填。保存不影响平台。</div><div class="form-grid">${textInput('task_id','独立追投任务ID／内部标识',t.task_id||'')}${selectInput('pricing_mode','出价类型',t.pricing_mode||'cost_bid',{cost_bid:'成本出价',target_roi:'目标ROI（仅记录，不套加价算法）'})}${selectInput('optimization_event','优化事件',t.optimization_event||'paid_order',{paid_order:'支付成交订单',net_order:'净成交订单',room_entry:'有效入房',other:'其他事件'})}${selectInput('status','当前状态',t.status||'active',{active:'可投放／进行中',stopped:'停止',blocked:'异常阻断'})}${numInput('bid','当前成本出价（元）',yn('bid'))}${numInput('bid_cap','批准最高出价（元）',yn('bid_cap'),'是设置上限，不是实际CPA保证')}${numInput('bid_step','允许价格步长（元）',yn('bid_step')??0.01,'向下取整，不超过上限')}${numInput('budget','当前任务总预算（元）',yn('budget'),'新建任务明确填0')}${numInput('spent','当前任务已消耗（元）',yn('spent'),'不是素材7天消耗')}${numInput('task_net_gmv','当前任务自己的净成交（元）',yn('task_net_gmv'))}${selectInput('task_basis','当前任务净额口径',t.task_basis||state.run.basis,{reported_net:'报表净额（定义待确认）',net_1h:'净额（扣1小时退款）',matured_net:'成熟净额（自行核实）'})}${selectInput('maturity','当前任务观察状态',t.maturity||'unknown',{unknown:'未核实',provisional:'初步／未回齐',matured:'已到约定观察期并核实'})}</div><h3>授权与下一次观察</h3><div class="form-grid">${numInput('addon_cap','本轮单素材追加上限（元）',yn('addon_cap'))}${numInput('risk_remaining','剩余毛广告风险授权（元）',yn('risk_remaining'),'包含当前任务未花额度，不以未发生收益冲销')}${numInput('fixed_test_budget','新任务固定测试额度（元）',yn('fixed_test_budget'),'预算为0的新任务使用；不是比例')}${numInput('review_hours','本次动作至少观察（小时）',t.review_hours,'业务自行确定；不是统一24小时')}${selectInput('diagnosis','已确认的主要限制',t.diagnosis||'unknown',{unknown:'原因未明 → 保持／诊断',budget:'预算限制 → 固定出价',bid:'有出价限制依据 → 固定预算'})}${textInput('diagnosis_note','诊断依据',t.diagnosis_note||'','不能只写预算没花完就认定出价低')}</div><div class="checks">${checkbox('product_ok','商品可售、库存和承接有效',t.product_ok)}${checkbox('scope_confirmed','已确认素材、SKU、路径与此独立任务范围对应',t.scope_confirmed)}${checkbox('context_confirmed','商品价格／承接等经营条件仍与验证时相符',t.context_confirmed)}${checkbox('mixed_scope_confirmed','历史有多SKU／多计划时，已独立核清本任务条件',t.mixed_scope_confirmed)}${checkbox('config_fresh','以上是当前实际设置，不是历史猜测值',t.config_fresh)}${checkbox('task_result_verified','当前独立任务自己的结果已核对，不直接继承素材整体ROI',t.task_result_verified)}</div><div class="form-footer"><small>已批准或执行未复核时，不允许覆盖当前基准。复核后需更新任务设置。</small><button class="primary">保存当前任务配置</button></div></form>`}
function otherModal(){const mo=state.modal;if(mo.type==='newworkspace')return modalShell('新建本地工作区',`<form data-form="workspace">${textInput('name','工作区名称','','例如：花花公子主号／计划内部名称')}<p>一个工作区对应一个计划范围，两条成交路径分别排名。</p><button class="primary">创建</button></form>`);const a=mo.action,p=a.payload;if(mo.type==='execute')return modalShell('记录人工已执行的配置',`<form data-form="execute" data-id="${a.id}"><div class="notice">先在平台执行，再回来记录。这个按钮不会修改任何广告。</div><h3>${e(p.creative_name)}</h3><div class="form-grid">${numInput('budget_new','实际新预算（元）',p.budget_new/100,'必须与本次批准方案一致')}${numInput('bid_new','实际新成本出价（元）',p.bid_new/100,'不同时增加第二变量')}</div>${textInput('note','执行备注','')}${checkbox('confirm_platform_done','我已人工执行上述设置，确认只是在此记录',false)}<button class="primary">记录执行并进入观察期</button></form>`);return modalShell('记录这一轮的真实结果',`<form data-form="review" data-id="${a.id}"><div class="notice">计划整体变化不等于本素材的因果增量。请用匹配的后续批次，记录真实费用和净额。${state.ws.kind==='demo'?'教学工作区允许提前演示复核，不代表实际可提前判定。':''}</div><h3>${e(p.creative_name)}</h3><div class="form-grid">${selectInput('maturity','结果状态','provisional',{pending:'待归因',provisional:'临时观察',matured:'达到约定窗口并核实'})}${numInput('cohort_spend','后续可比批次实际消耗（元）',null)}${numInput('cohort_net_gmv','对应批次净成交（元）',null)}${numInput('net_orders','对应批次净订单',null,'',{step:1})}${numInput('settled_spend','本笔预留内已花金额（元）',null,`仅本笔新增授权 ${money(a.reserved)} 内实际支出；不重复填全任务成本`)}</div>${textInput('note','复核证据与解释','')}${checkbox('passed','人工判断本轮可比且通过（还会检查ROI与订单门槛）',false)}${checkbox('reservation_closed','本笔追加授权已结束；已花部分结算，未花部分释放',false)}<button class="primary">保存复核</button></form>`)}
function modalShell(title:string,body:string){return `<div class="modal-backdrop"><section class="modal"><header><h2>${e(title)}</h2><button class="icon-btn" data-action="close">×</button></header><div class="modal-body">${body}</div></section></div>`}
function legacyRender(){const root=$('#root');if(!root)return;if(!state.ws){root.innerHTML='<div class="loading-screen"><div class="logo">↗</div><h2>正在连接本地工作台…</h2><p>通过启动脚本运行，界面不依赖外部CDN。</p></div>';return}root.innerHTML=`<div class="app-layout"><aside class="sidebar"><a class="brand" href="#"><span class="brand-symbol">↗</span><div>投流实验室<small>PAID VIDEO OPTIMIZER</small></div></a><div class="workspace-select"><small>本地工作区</small><select id="workspace-select">${state.workspaces.map((w:Obj)=>`<option value="${w.id}" ${w.id===state.ws.id?'selected':''}>${e(w.name)}</option>`).join('')}</select><button class="text-btn" data-action="newworkspace">＋ 新建工作区</button></div><nav>${Object.entries(names).map(([key,value],n)=>`<button class="${state.view===key?'active':''}" data-action="view" data-value="${key}"><span>${['◈','↑','▦','⚙','↗','◷'][n]}</span>${e(value)}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="status-dot"></div> 数据保存在本机<p>不调用大模型<br>不自动执行投放</p><button class="text-btn" data-action="demo">体验教学模拟 ↗</button></div></aside><main><header class="topbar"><span>${e(names[state.view])} <i>/</i> ${e(state.ws.name)}</span><div><span class="local-tag">● 本地</span><button class="ghost" data-action="refresh">刷新</button></div></header><div class="main-content">${workspaceBanner()}${({dashboard,imports:importsView,materials,settings,actions:actionsView,history:historyView} as Obj)[state.view]()}</div><footer>V1.0 · 排序分不是成功率 · 5% / 10%是限额试探档位 · 未提供的数据保持缺失</footer></main></div><div id="busy" class="${state.busy?'show':''}"><span></span>处理中</div>${state.modal?(state.modal.type==='detail'?detailModal():otherModal()):''}`;bindChanges()}
function bindChanges(){const q=(s:string)=>document.querySelector(s) as HTMLInputElement|HTMLSelectElement|null;q('#workspace-select')?.addEventListener('change',()=>guard(async()=>{setWorkspace(state.workspaces.find((w:Obj)=>w.id===q('#workspace-select')!.value));await refresh();await restoreRanking();render()}));q('#objective')?.addEventListener('change',()=>guard(async()=>{state.objective=q('#objective')!.value;await runRanking()}));q('#exposure-tier')?.addEventListener('change',()=>guard(async()=>{state.exposureTier=q('#exposure-tier')!.value;await runRanking()}));q('#select30')?.addEventListener('change',()=>{state.i30=q('#select30')!.value;state.omit30=!state.i30;state.i7='';state.omit7=false;autoSelect();render()});q('#select7')?.addEventListener('change',()=>{state.i7=q('#select7')!.value;state.omit7=!state.i7});q('#rankmode')?.addEventListener('change',()=>state.mode=q('#rankmode')!.value);q('#queuefilter')?.addEventListener('change',()=>{state.filter=q('#queuefilter')!.value;state.page=0;render()});q('#search')?.addEventListener('change',()=>{state.query=q('#search')!.value;state.page=0;render()});q('#uploads')?.addEventListener('change',(ev)=>{const fs=(ev.target as HTMLInputElement).files;if(fs)guard(()=>uploadFiles(Array.from(fs)))});const dz=$('#dropzone');dz?.addEventListener('dragover',ev=>{ev.preventDefault();dz.classList.add('dragging')});dz?.addEventListener('dragleave',()=>dz.classList.remove('dragging'));dz?.addEventListener('drop',ev=>{ev.preventDefault();dz.classList.remove('dragging');const f=(ev as DragEvent).dataTransfer?.files;if(f)guard(()=>uploadFiles(Array.from(f)))})}
async function uploadFiles(files:File[]){for(const file of files){const form=new FormData();form.append('workspace_id',state.ws.id);form.append('file',file);await api('/imports/preview','POST',form)}await refresh();state.view='imports';render();toast('文件已解析，请核对窗口和范围后确认。')}
async function openDetail(cid:string,tab='metrics'){const item=state.run?.results.find((x:Obj)=>x.creative_id===cid);if(!item)return;[state.task,state.ledger]=await Promise.all([api(`/workspaces/${state.ws.id}/tasks/${item.path}/${encodeURIComponent(cid)}`),api(`/workspaces/${state.ws.id}/ledger`)]);state.tab=tab;state.modal={type:'detail',item};render()}
document.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest('[data-action]') as HTMLElement|null;if(!el)return;ev.preventDefault();const a=el.dataset.action,v=el.dataset.value,id=el.dataset.id||'';if(a==='close'){state.modal=null;render();return}if(a==='view'){state.view=v;state.page=0;render();return}if(a==='detail-tab'){state.tab=v;render();return}if(a==='path'){state.path=v;state.run=null;state.i30='';state.i7='';state.omit7=false;state.omit30=false;state.proposals=[];autoSelect();render();return}if(a==='newworkspace'){state.modal={type:'newworkspace'};render();return}if(a==='queue'){state.filter=v;state.view='materials';state.page=0;render();return}if(a==='prev'||a==='next'){state.page+=a==='next'?1:-1;render();return}guard(async()=>{
 if(a==='exposure'){state.exposureTier=v;await runRanking()}
 if(a==='rank'){await runRanking();toast('评分已更新：'+state.run.results.length+'条素材完成评分，当前曝光层展示'+state.run.top_ids.length+'条候选。')}
 if(a==='refresh'){await refresh();render()}
 if(a==='load-real'){const ws=await api('/examples/load','POST',{});setWorkspace(ws);await refresh();state.path='live';autoSelect();state.view='dashboard';await runRanking();toast('已载入4份合成示例，仅供历史回放。')}
 if(a==='demo'){const d=await api('/demo','POST',{});setWorkspace(d.workspace);await refresh();state.path='live';state.i30=d.import_30;state.i7=d.import_7;state.view='dashboard';await runRanking();toast('教学模拟已准备，可生成并复核试探动作。')}
 if(a==='detail'||a==='detail-task')await openDetail(id,a==='detail'?'metrics':'task');
 if(a==='propose'){const d=await api('/recommendation-runs','POST',{run_id:state.run.id});state.proposals=d.proposals;await refresh();render();const count=d.proposals.filter((p:Obj)=>['BUDGET_TEST','BID_TEST','NEW_BOOST_TEST'].includes(p.action_type)).length;toast(count?'已生成'+count+'条数值提案，尚未批准或执行。':'检查完成：本轮没有可执行的数值动作，请查看原因与待补信息。');document.querySelector('.proposal-grid')?.scrollIntoView({behavior:'smooth',block:'start'})}
 if(a==='approve'){if(!window.confirm('只在本地批准并预留额度，不会修改平台。确认？'))return;await api(`/recommendations/${id}/approve`,'POST',{confirm:true});await refresh();state.view='actions';state.modal=null;render();toast('本地批准成功。请人工到平台执行后再记录。')}
 if(a==='cancel'){await api(`/actions/${id}/cancel`,'POST',{reason:'用户取消未执行提案'});await refresh();render();toast('未执行提案已取消。')}
 if(a==='execute-modal'||a==='review-modal'){state.modal={type:a==='execute-modal'?'execute':'review',action:state.actions.find((x:Obj)=>x.id===id)};render()}
 if(a==='load-run'){await loadRankingSnapshot(id);state.view='dashboard';render()}
 if(a==='audit'){state.audit=await api(`/workspaces/${state.ws.id}/audit`);render()}
})});
function formNumber(f:FormData,k:string,scale=1):number|null{const v=f.get(k);if(v===null||String(v).trim()==='')return null;const n=Number(v);if(!Number.isFinite(n))throw new Error(k+'不是数值');return scale===100?Math.round(n*100):n*scale}
document.addEventListener('submit',ev=>{const form=ev.target as HTMLFormElement;if(!form.dataset.form)return;ev.preventDefault();const f=new FormData(form);const n=form.dataset.form;guard(async()=>{
 if(n==='workspace'){const ws=await api('/workspaces','POST',{name:f.get('name')});setWorkspace(ws);await refresh();render()}
 if(n==='confirm-import'){const mp:Obj={};for(const [k,v] of f)if(k.startsWith('map_'))mp[k.slice(4)]=v||null;await api(`/imports/${form.dataset.id}/confirm`,'POST',{path:f.get('path'),period_start:f.get('period_start'),period_end:f.get('period_end'),basis:f.get('basis'),basis_note:f.get('basis_note'),scope:f.get('scope'),complete:f.has('complete'),scope_confirmed:f.has('scope_confirmed'),sheet:f.get('sheet'),header_row:formNumber(f,'header_row'),mapping:mp});state.path=f.get('path');state.i30='';state.i7='';state.omit30=false;state.omit7=false;await refresh();render();toast('快照已保存，可在候选TOP3中计算。')}
 if(n==='reuse-history'){await api(`/workspaces/${state.ws.id}/chengfang/imports/${form.dataset.id}/reuse`,'POST',{plan_id:f.get('plan_id'),path:state.imports.find((x:Obj)=>x.id===form.dataset.id)?.path,scope:f.get('scope'),cost_basis:'marketing_cost',cost_grain:'material_attributable',plan_marketing_cost:formNumber(f,'plan_marketing_cost',100)});await refresh();render();toast('已从历史导入创建乘方诊断快照。')}
 if(n==='settings'){const c={...state.ws.config,delivery_mode:f.get('delivery_mode'),roi_min:formNumber(f,'roi_min'),min_orders:formNumber(f,'min_orders'),smoothing_yuan:formNumber(f,'smoothing_yuan'),reference_roi:formNumber(f,'reference_roi'),freshness_days:formNumber(f,'freshness_days'),budget_total:formNumber(f,'budget_total',100),external_spent:formNumber(f,'external_spent',100)??0,external_committed:formNumber(f,'external_committed',100)??0,threshold_note:f.get('threshold_note'),threshold_confirmed:f.has('threshold_confirmed'),weights:{'30':(formNumber(f,'w_30')||0)/100,'7':(formNumber(f,'w_7')||0)/100,trend:(formNumber(f,'w_trend')||0)/100,stability:(formNumber(f,'w_stability')||0)/100}};await api(`/workspaces/${state.ws.id}/config`,'PUT',c);await refresh();state.proposals=[];render();toast('已保存。旧排序保留，生成新建议前请重新计算。')}
 if(n==='task'){const body:Obj={};for(const [k,v] of f)body[k]=v;for(const k of ['bid','bid_cap','bid_step','budget','spent','addon_cap','risk_remaining','fixed_test_budget','task_net_gmv'])body[k]=formNumber(f,k,100);body.review_hours=formNumber(f,'review_hours');for(const k of ['scope_confirmed','context_confirmed','mixed_scope_confirmed','config_fresh','product_ok','task_result_verified'])body[k]=f.has(k);const x=state.modal.item;state.task=await api(`/workspaces/${state.ws.id}/tasks/${x.path}/${x.creative_id}`,'PUT',body);toast('配置已保存，未修改平台。回到TOP3生成建议。');render()}
 if(n==='execute'){await api(`/actions/${form.dataset.id}/execution`,'POST',{budget_new:formNumber(f,'budget_new',100),bid_new:formNumber(f,'bid_new',100),confirm_platform_done:f.has('confirm_platform_done'),note:f.get('note')});await refresh();state.modal=null;render();toast('执行记录已保存，等待约定观察期。')}
 if(n==='review'){const body:Obj={maturity:f.get('maturity'),note:f.get('note'),passed:f.has('passed'),reservation_closed:f.has('reservation_closed')};for(const k of ['cohort_spend','cohort_net_gmv','settled_spend'])body[k]=formNumber(f,k,100);body.net_orders=formNumber(f,'net_orders');await api(`/actions/${form.dataset.id}/review`,'POST',body);await refresh();state.modal=null;render();toast('复核已保存。下一轮前请更新当前任务的实际设置。')}
})});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.modal){state.modal=null;render()}});
async function boot(){render();try{await api('/health');state.workspaces=await api('/workspaces');if(!state.workspaces.length)state.workspaces=[await api('/workspaces','POST',{name:'我的投流'})];const saved=localRemember.get('optimizer_workspace');state.ws=state.workspaces.find((w:Obj)=>w.id===saved)||state.workspaces[0];await refresh();await restoreRanking();render()}catch(err:any){$('#root')!.innerHTML=`<div class="loading-screen"><h2>请先启动本地服务</h2><p>双击“启动-Mac.command”或“启动-Windows.bat”，再访问启动窗口显示的本地地址。</p><pre>${e(err.message)}</pre></div>`}}
function cfSettings(){const c=state.ws.config;return hero('诊断规则，<em>显式确认。</em>','成方模式不生成预算、出价、批准或预留。阈值和方向规则会被冻结到每次诊断。')+`<form data-form="chengfang-settings" class="settings-grid"><div class="panel"><h2>诊断门槛</h2><div class="form-grid">${numInput('smoothing_yuan','ROI平滑消耗（元）',c.smoothing_yuan)}${numInput('diagnosis_min_impressions','最低曝光',c.diagnosis_min_impressions,'低于此值继续观察',{step:1,min:1})}${numInput('diagnosis_min_spend_yuan','最低营销消耗（元）',c.diagnosis_min_spend_yuan,'低于此值补测变体')}${numInput('diagnosis_required_periods','所需可比周期',c.diagnosis_required_periods,'至少2期',{step:1,min:2})}</div><button class="primary">保存诊断规则</button></div><div class="panel"><h2>内容方向规则</h2><p>阈值完整且满足两期可比后，才会给出保留赛马、停止生产或扩产方向。</p><div class="form-grid">${selectInput('primary_objective','主目标',c.direction_rules?.primary_objective||'roi',{exposure:'最大化曝光',orders:'最大化成单',roi:'最大化ROI'})}${numInput('min_creatives','最少素材数',c.direction_rules?.min_creatives||1,'',{step:1,min:1})}${numInput('expand_primary_ratio','扩产主目标增幅',Number(c.direction_rules?.expand_primary_ratio||.2)*100,'百分比',{min:1})}${numInput('expand_roi_ratio','扩产ROI增幅',Number(c.direction_rules?.expand_roi_ratio||.2)*100,'百分比',{min:1})}${numInput('expand_order_ratio','扩产订单增幅',Number(c.direction_rules?.expand_order_ratio||.2)*100,'百分比',{min:1})}${numInput('stop_primary_ratio','停止主目标降幅',Number(c.direction_rules?.stop_primary_ratio||.2)*100,'百分比',{min:1})}${numInput('stop_roi_ratio','停止ROI降幅',Number(c.direction_rules?.stop_roi_ratio||.2)*100,'百分比',{min:1})}${numInput('stop_order_ratio','停止订单降幅',Number(c.direction_rules?.stop_order_ratio||.2)*100,'百分比',{min:1})}</div></div></form>`}
function cfContextView(){const c=cfContext()?.config||{};const caps=['base_delivery','star_select','creator_marketing','creator_commission_bid'];return hero('计划上下文，<em>先于诊断。</em>','上下文、能力标识与操作日志都按路径和计划保存；后续修改不会改写已保存诊断。')+cfSelector()+`<div class="settings-grid"><form data-form="chengfang-context" class="panel"><h2>计划与能力</h2><div class="form-grid">${textInput('plan_id','计划ID',state.cf.planId||'')}${selectInput('status','计划状态',c.status||'active',{active:'active',paused:'paused',stopped:'stopped'})}${textInput('started_at','开始时间',c.started_at||new Date().toISOString())}${numInput('marketing_roi_target','营销ROI目标',c.marketing_roi_target??null)}${textInput('basis_note','口径说明',c.basis_note||'')}</div><div class="checks">${caps.map(k=>checkbox(k,({base_delivery:'基础投放',star_select:'星选',creator_marketing:'达人营销',creator_commission_bid:'达人佣金出价'} as Obj)[k],Boolean(c[k]))).join('')}${checkbox('base_delivery_only','仅基础投放（允许整体消耗）',Boolean(c.base_delivery_only))}</div><button class="primary">保存计划上下文</button></form><form data-form="chengfang-operation" class="panel"><h2>操作日志</h2><div class="form-grid">${selectInput('kind','变更类型','budget_changed',{roi_target_changed:'ROI目标变更',budget_changed:'预算变更',capability_changed:'能力变更',product_changed:'商品变更',landing_changed:'承接页变更',material_batch_added:'素材批次新增'})}${textInput('occurred_at','发生时间',new Date().toISOString())}${textInput('value','变更值／标识','')}${textInput('note','操作说明','')}</div><p>数值类型填写数值；商品或承接填写标识；素材批次用逗号分隔素材ID。</p><button class="secondary" ${state.cf.planId?'':'disabled'}>追加操作日志</button></form></div><div class="panel"><h2>已记录操作</h2>${state.cf.operations.length?state.cf.operations.map((o:Obj)=>`<p><b>${e(o.kind)}</b> · ${e(dt(o.occurred_at))} · ${e(o.payload?.note||'')}<small>${e(JSON.stringify(o.payload||{}))}</small></p>`).join(''):'<p class="muted">尚无操作日志。</p>'}</div>`}
function cfHistory(){return hero('诊断回收与复盘','选择已保存的诊断回放冻结内容；当前配置、标签或上下文变化不会改写它。')+cfSelector()+`<div class="panel"><h2>已保存素材诊断</h2>${state.cf.diagnoses.length?`<div class="table-wrap"><table><thead><tr><th>生成时间</th><th>计划</th><th>冻结导入</th><th>素材 / 内容方向</th><th></th></tr></thead><tbody>${state.cf.diagnoses.map((d:Obj)=>{const p=d.payload||{};return `<tr><td>${e(dt(d.created_at))}</td><td>${e(d.plan_id)}</td><td>${e((p.frozen_inputs?.import_ids||[]).join('、'))}</td><td>${(p.material_cards||[]).length} / ${(p.direction_cards||[]).length}</td><td><button class="text-btn" data-action="load-chengfang-diagnosis" data-id="${e(d.id)}">回放冻结结果 →</button></td></tr>`}).join('')}</tbody></table></div>`:empty('尚无诊断','选择当前完整7天导入并生成素材诊断后，结果会在此保留。')}</div>`}
function cfLabelModal(){const id=state.modal.creativeId;const profile=state.cf.profiles.find((x:Obj)=>x.creative_id===id);const labels=profile?.labels||{};return modalShell('编辑素材标签',`<form data-form="chengfang-labels" data-id="${e(id)}"><p>${e(id)} · ${e(state.cf.planId)} · ${e(pathName(state.path))}</p><div class="form-grid">${Object.entries(cfLabelKeys).map(([key,label])=>textInput(key,label,labels[key]||'')).join('')}</div><button class="primary" ${state.cf.planId?'':'disabled'}>保存标签</button></form>`)}
function render(){const root=$('#root');if(!root)return;if(!state.ws){root.innerHTML='<div class="loading-screen"><div class="logo">↗</div><h2>正在连接本地工作台…</h2><p>通过启动脚本运行，界面不依赖外部CDN。</p></div>';return}const nav=visibleNames(),views:Obj={dashboard,imports:importsView,materials,settings,isChengfang:isChengfang,actions:actionsView,context:cfContextView,history:isChengfang()?cfHistory:historyView};root.innerHTML=`<div class="app-layout"><aside class="sidebar"><a class="brand" href="#"><span class="brand-symbol">↗</span><div>投流实验室<small>PAID VIDEO OPTIMIZER</small></div></a><div class="workspace-select"><small>本地工作区</small><select id="workspace-select">${state.workspaces.map((w:Obj)=>`<option value="${w.id}" ${w.id===state.ws.id?'selected':''}>${e(w.name)}</option>`).join('')}</select><button class="text-btn" data-action="newworkspace">＋ 新建工作区</button></div><nav>${Object.entries(nav).map(([key,value],n)=>`<button class="${state.view===key?'active':''}" data-action="view" data-value="${key}"><span>${['◈','↑','▦','⚙','↗','◷'][n]}</span>${e(value)}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="status-dot"></div> 数据保存在本机<p>不调用大模型<br>不自动执行投放</p>${isChengfang()?'':'<button class="text-btn" data-action="demo">体验教学模拟 ↗</button>'}</div></aside><main><header class="topbar"><span>${e(nav[state.view])} <i>/</i> ${e(state.ws.name)}</span><div><span class="local-tag">● 本地</span><button class="ghost" data-action="refresh">刷新</button></div></header><div class="main-content">${workspaceBanner()}${views[state.view]()}</div><footer>${isChengfang()?'V1.0 · 成方模式只保存素材诊断与内容决策，不生成预算、出价、批准或预留。':'V1.0 · 排序分不是成功率 · 5% / 10%是限额试探档位 · 未提供的数据保持缺失'}</footer></main></div><div id="busy" class="${state.busy?'show':''}"><span></span>处理中</div>${state.modal?(state.modal.type==='cf-label'?cfLabelModal():state.modal.type==='detail'?detailModal():otherModal()):''}`;bindChanges();bindCfChanges()}
function bindCfChanges(){const q=(s:string)=>document.querySelector(s) as HTMLInputElement|HTMLSelectElement|null;q('#chengfang-plan')?.addEventListener('change',()=>guard(async()=>{state.cf.planId=q('#chengfang-plan')!.value;state.cf.diagnosis=null;state.cf.error='';await refreshCf();render()}));q('#chengfang-current')?.addEventListener('change',()=>{state.cf.currentId=q('#chengfang-current')!.value;render()});q('#chengfang-prior')?.addEventListener('change',()=>{state.cf.priorId=q('#chengfang-prior')!.value})}
document.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest('[data-action]') as HTMLElement|null;if(!el||!isChengfang())return;const a=el.dataset.action,id=el.dataset.id||'';if(a==='chengfang-labels'){ev.preventDefault();state.modal={type:'cf-label',creativeId:id};render();return}if(a==='load-chengfang-diagnosis'){ev.preventDefault();guard(async()=>{state.cf.diagnosis=await api(`/chengfang/diagnosis-runs/${id}`);state.view='dashboard';render()});return}if(a==='chengfang-diagnose'){ev.preventDefault();guard(async()=>{try{state.cf.error='';state.cf.diagnosis=await api('/chengfang/diagnosis-runs','POST',{workspace_id:state.ws.id,plan_id:state.cf.planId,path:state.path,current_import_id:state.cf.currentId,prior_import_id:state.cf.priorId||null});await refreshCf();render()}catch(err:any){state.cf.error=err.message||String(err);render();toast(state.cf.error,true)}})}});
async function cfClick(action:string,id:string){if(action==='chengfang-labels'){state.modal={type:'cf-label',creativeId:id};render();return}if(action==='load-chengfang-diagnosis'){state.cf.diagnosis=await api(`/chengfang/diagnosis-runs/${id}`);state.view='dashboard';render();return}if(action==='chengfang-diagnose'){try{state.cf.error='';state.cf.diagnosis=await api('/chengfang/diagnosis-runs','POST',{workspace_id:state.ws.id,plan_id:state.cf.planId,path:state.path,current_import_id:state.cf.currentId,prior_import_id:state.cf.priorId||null});await refreshCf();render()}catch(err:any){state.cf.error=err.message||String(err);render();toast(state.cf.error,true)}}}
document.addEventListener('click',ev=>{const el=(ev.target as HTMLElement).closest('[data-action]') as HTMLElement|null;if(!el||!isChengfang()||!['chengfang-labels','load-chengfang-diagnosis','chengfang-diagnose'].includes(el.dataset.action||''))return;ev.preventDefault();ev.stopImmediatePropagation();guard(()=>cfClick(el.dataset.action||'',el.dataset.id||''))},true);
async function cfSubmit(form:HTMLFormElement){const f=new FormData(form),kind=form.dataset.form;if(kind==='chengfang-labels'){const labels:Obj={};for(const key of Object.keys(cfLabelKeys))labels[key]=f.get(key);await api(`/workspaces/${state.ws.id}/chengfang/plans/${encodeURIComponent(state.cf.planId)}/materials/${encodeURIComponent(form.dataset.id||'')}`,'PUT',{path:state.path,labels});await refreshCf();state.modal=null;render();toast('标签已按计划保存。')}if(kind==='chengfang-context'){const body:Obj={plan_id:f.get('plan_id'),path:state.path,status:f.get('status'),started_at:f.get('started_at'),marketing_roi_target:formNumber(f,'marketing_roi_target'),basis_note:f.get('basis_note'),base_delivery_only:f.has('base_delivery_only')};for(const k of ['base_delivery','star_select','creator_marketing','creator_commission_bid'])body[k]=f.has(k);await api(`/workspaces/${state.ws.id}/chengfang/context`,'PUT',body);state.cf.planId=String(body.plan_id);await refresh();render();toast('计划上下文已保存。')}if(kind==='chengfang-operation'){const operation=String(f.get('kind')),value=String(f.get('value')||'').trim();let payload:Obj={};if(operation==='roi_target_changed')payload={roi_target:Number(value)};else if(operation==='budget_changed')payload={budget:Number(value)};else if(operation==='capability_changed')payload={status:value||'active'};else if(operation==='product_changed')payload={product_id:value};else if(operation==='landing_changed')payload={landing_id:value};else payload={creative_ids:value.split(',').map(x=>x.trim()).filter(Boolean)};await api(`/workspaces/${state.ws.id}/chengfang/operations`,'POST',{path:state.path,plan_id:state.cf.planId,kind:operation,occurred_at:f.get('occurred_at'),note:f.get('note'),payload});await refreshCf();render();toast('操作日志已追加。')}if(kind==='chengfang-settings'){const ratio=(key:string)=>(formNumber(f,key)||0)/100,c={...state.ws.config,smoothing_yuan:formNumber(f,'smoothing_yuan'),diagnosis_min_impressions:formNumber(f,'diagnosis_min_impressions'),diagnosis_min_spend_yuan:formNumber(f,'diagnosis_min_spend_yuan'),diagnosis_required_periods:formNumber(f,'diagnosis_required_periods'),direction_rules:{primary_objective:f.get('primary_objective'),min_creatives:formNumber(f,'min_creatives'),expand_primary_ratio:ratio('expand_primary_ratio'),expand_roi_ratio:ratio('expand_roi_ratio'),expand_order_ratio:ratio('expand_order_ratio'),stop_primary_ratio:ratio('stop_primary_ratio'),stop_roi_ratio:ratio('stop_roi_ratio'),stop_order_ratio:ratio('stop_order_ratio')}};await api(`/workspaces/${state.ws.id}/config`,'PUT',c);await refresh();render();toast('诊断规则已保存；已保存诊断保持冻结。')}}
document.addEventListener('submit',ev=>{const form=ev.target as HTMLFormElement;if(!isChengfang()||!form.dataset.form?.startsWith('chengfang-'))return;ev.preventDefault();ev.stopImmediatePropagation();guard(()=>cfSubmit(form))},true);
boot();
